from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    sep_rows = [
        r for r in range(h)
        if len(set(grid[r])) == 1 and grid[r][0] != 0
    ]
    sep_cols = [
        c for c in range(w)
        if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != 0
    ]

    separators = set(sep_rows)  # collect separator colors to exclude from background count
    sep_colors = {grid[r][0] for r in sep_rows} | {grid[0][c] for c in sep_cols}
    counts = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in separators and c not in sep_cols
        and grid[r][c] not in sep_colors
    )
    background = counts.most_common(1)[0][0]

    row_bounds = [-1] + sep_rows + [h]
    col_bounds = [-1] + sep_cols + [w]
    out = []

    for ri in range(len(row_bounds) - 1):
        row = []
        for ci in range(len(col_bounds) - 1):
            r0, r1 = row_bounds[ri] + 1, row_bounds[ri + 1]
            c0, c1 = col_bounds[ci] + 1, col_bounds[ci + 1]
            anomalies = sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            )
            row.append(1 if anomalies >= 2 else background)
        out.append(row)
    return out
